import { InvalidOrderTransitionError, InvalidValueError } from '../errors/DomainError';
import { requireNonEmpty } from '../shared/guards';
import { OrderLine, type OrderLineSnapshot } from '../value-objects/OrderLine';
import { canTransition, type OrderStatus } from '../value-objects/OrderStatus';

export interface StatusChange {
  readonly status: OrderStatus;
  readonly at: Date;
}

export interface OrderSnapshot {
  readonly id: string;
  readonly customerId: string;
  readonly status: OrderStatus;
  readonly lines: readonly OrderLineSnapshot[];
  readonly history: readonly StatusChange[];
}

export interface NewOrder {
  readonly id: string;
  readonly customerId: string;
  readonly lines: readonly OrderLineSnapshot[];
  readonly at: Date;
}

/** A customer's order and its progress through fulfilment. */
export class Order {
  private constructor(
    readonly id: string,
    readonly customerId: string,
    private readonly orderLines: readonly OrderLine[],
    private currentStatus: OrderStatus,
    private readonly statusHistory: StatusChange[],
  ) {}

  static place(props: NewOrder): Order {
    const lines = props.lines.map((line) => OrderLine.create(line));
    if (lines.length === 0) {
      throw new InvalidValueError('An order must contain at least one line');
    }
    const productIds = new Set(lines.map((line) => line.productId));
    if (productIds.size !== lines.length) {
      throw new InvalidValueError('An order must not list the same product more than once');
    }
    return new Order(
      requireNonEmpty(props.id, 'id'),
      requireNonEmpty(props.customerId, 'customerId'),
      lines,
      'placed',
      [{ status: 'placed', at: new Date(props.at.getTime()) }],
    );
  }

  static restore(snapshot: OrderSnapshot): Order {
    return new Order(
      snapshot.id,
      snapshot.customerId,
      snapshot.lines.map((line) => OrderLine.create(line)),
      snapshot.status,
      snapshot.history.map((change) => ({ status: change.status, at: new Date(change.at.getTime()) })),
    );
  }

  get status(): OrderStatus {
    return this.currentStatus;
  }

  get lines(): readonly OrderLine[] {
    return this.orderLines;
  }

  get totalCents(): number {
    return this.orderLines.reduce((total, line) => total + line.subtotalCents, 0);
  }

  transitionTo(target: OrderStatus, at: Date): void {
    if (!canTransition(this.currentStatus, target)) {
      throw new InvalidOrderTransitionError(this.id, this.currentStatus, target);
    }
    this.currentStatus = target;
    this.statusHistory.push({ status: target, at: new Date(at.getTime()) });
  }

  toSnapshot(): OrderSnapshot {
    return {
      id: this.id,
      customerId: this.customerId,
      status: this.currentStatus,
      lines: this.orderLines.map((line) => line.toSnapshot()),
      history: this.statusHistory.map((change) => ({
        status: change.status,
        at: new Date(change.at.getTime()),
      })),
    };
  }
}

