import { InsufficientStockError, StockAccountingError } from '../errors/DomainError';
import { requireNonEmpty, requireNonNegativeInteger } from '../shared/guards';
import type { Quantity } from '../value-objects/Quantity';

export interface ProductSnapshot {
  readonly id: string;
  readonly name: string;
  readonly priceCents: number;
  /** Units physically held in stock. */
  readonly onHand: number;
  /** Units held for orders that have not shipped yet. */
  readonly reserved: number;
}

export interface NewProduct {
  readonly id: string;
  readonly name: string;
  readonly priceCents: number;
  readonly initialStock: number;
}

/** A catalogue product together with its stock position. */
export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    readonly priceCents: number,
    private onHand: number,
    private reserved: number,
  ) {}

  static create(props: NewProduct): Product {
    return Product.restore({
      id: props.id,
      name: props.name,
      priceCents: props.priceCents,
      onHand: props.initialStock,
      reserved: 0,
    });
  }

  static restore(snapshot: ProductSnapshot): Product {
    const onHand = requireNonNegativeInteger(snapshot.onHand, 'onHand');
    const reserved = requireNonNegativeInteger(snapshot.reserved, 'reserved');
    if (reserved > onHand) {
      throw new StockAccountingError(`Product ${snapshot.id} reserves more units than it holds`);
    }
    return new Product(
      requireNonEmpty(snapshot.id, 'id'),
      requireNonEmpty(snapshot.name, 'name'),
      requireNonNegativeInteger(snapshot.priceCents, 'priceCents'),
      onHand,
      reserved,
    );
  }

  /** Units that can still be reserved by new orders. */
  get available(): number {
    return this.onHand - this.reserved;
  }

  canReserve(quantity: Quantity): boolean {
    return quantity.value <= this.available;
  }

  reserve(quantity: Quantity): void {
    if (!this.canReserve(quantity)) {
      throw new InsufficientStockError([
        { productId: this.id, requested: quantity.value, available: this.available },
      ]);
    }
    this.reserved += quantity.value;
  }

  /** Returns reserved units to the available pool. */
  release(quantity: Quantity): void {
    this.requireReserved(quantity);
    this.reserved -= quantity.value;
  }

  /** Removes reserved units from stock because they have left the warehouse. */
  commit(quantity: Quantity): void {
    this.requireReserved(quantity);
    this.reserved -= quantity.value;
    this.onHand -= quantity.value;
  }

  toSnapshot(): ProductSnapshot {
    return {
      id: this.id,
      name: this.name,
      priceCents: this.priceCents,
      onHand: this.onHand,
      reserved: this.reserved,
    };
  }

  private requireReserved(quantity: Quantity): void {
    if (quantity.value > this.reserved) {
      throw new StockAccountingError(
        `Product ${this.id} has ${this.reserved} reserved units, cannot settle ${quantity.value}`,
      );
    }
  }
}

